Best practices:
- One assertion per test (when possible)
- Descriptive test names
- Tests should be independent
- Use setup/teardown for common initialization

Mocking replaces real dependencies with controlled fake objects to test components in isolation.

```python
# Python with unittest.mock
from unittest.mock import Mock, patch, MagicMock
import pytest

# Code to test
class PaymentGateway:
    def charge(self, amount):
        # Real API call
        return requests.post("https://api.payment.com/charge", json={"amount": amount})

class OrderService:
    def __init__(self, payment_gateway):
        self.payment_gateway = payment_gateway

    def process_order(self, order_id, amount):
        if amount <= 0:
            raise ValueError("Invalid amount")
        response = self.payment_gateway.charge(amount)
        if response.status_code == 200:
            return {"status": "success", "order_id": order_id}
        return {"status": "failed"}

# Test with mocking
def test_process_order_success():
    # Create mock
    mock_gateway = Mock()
    mock_response = Mock()
    mock_response.status_code = 200
    mock_gateway.charge.return_value = mock_response

    service = OrderService(mock_gateway)
    result = service.process_order(123, 100)

    assert result["status"] == "success"
    mock_gateway.charge.assert_called_once_with(100)

def test_process_order_failure():
    mock_gateway = Mock()
    mock_response = Mock()
    mock_response.status_code = 500
    mock_gateway.charge.return_value = mock_response

    service = OrderService(mock_gateway)
    result = service.process_order(123, 100)

    assert result["status"] == "failed"

# Using patch to mock external dependencies
@patch('requests.post')
def test_with_patch(mock_post):
    mock_response = MagicMock()
    mock_response.status_code = 200
    mock_response.json.return_value = {"id": "txn_123"}
    mock_post.return_value = mock_response

    result = make_api_call()
    mock_post.assert_called_once()
```

