// Java with Mockito
import org.junit.jupiter.api.Test;
import org.mockito.Mock;
import org.mockito.InjectMocks;
import static org.mockito.Mockito.*;

class OrderServiceTest {
    @Mock
    private PaymentGateway paymentGateway;

    @InjectMocks
    private OrderService orderService;

    @Test
    void testProcessOrderSuccess() {
        // Given
        when(paymentGateway.charge(anyDouble())).thenReturn(
            new PaymentResponse(200, "success")
        );

        // When
        OrderResult result = orderService.processOrder(123, 100.0);

        // Then
        assertEquals(OrderStatus.SUCCESS, result.getStatus());
        verify(paymentGateway, times(1)).charge(100.0);
    }

    @Test
    void testProcessOrderFailure() {
        when(paymentGateway.charge(100.0)).thenThrow(
            new PaymentException("Payment failed")
        );

        OrderResult result = orderService.processOrder(123, 100.0);

        assertEquals(OrderStatus.FAILED, result.getStatus());
    }
}
