Mocking best practices:
- Mock external dependencies only
- Don't mock what you don't own
- Verify interactions when important
- Use spies to check function calls

Integration testing verifies that multiple components or systems work together correctly. It tests interactions between modules, databases, external APIs, and services.

```python
# Python with pytest and requests
import pytest
import requests
from fastapi import FastAPI
from fastapi.testclient import TestClient

# Testing a real API endpoint
def test_api_integration():
    response = requests.get("https://jsonplaceholder.typicode.com/users/1")
    assert response.status_code == 200
    data = response.json()
    assert data["id"] == 1
    assert "name" in data

# Testing FastAPI application with TestClient
app = FastAPI()

@app.post("/orders")
def create_order(order_data: dict):
    # Would normally save to database
    return {"order_id": 123, "status": "created"}

@app.get("/orders/{order_id}")
def get_order(order_id: int):
    return {"order_id": order_id, "total": 99.99}

class TestOrderAPI:
    def setup_method(self):
        self.client = TestClient(app)

    def test_create_and_retrieve_order(self):
        # Create order
        create_response = self.client.post("/orders", json={"product": "laptop", "quantity": 1})
        assert create_response.status_code == 200
        order_id = create_response.json()["order_id"]

        # Retrieve order
        get_response = self.client.get(f"/orders/{order_id}")
        assert get_response.status_code == 200
        assert get_response.json()["order_id"] == order_id
