# Database integration test
import pytest
from sqlalchemy import create_engine
from sqlalchemy.orm import sessionmaker
from models import Base, User, Order

@pytest.fixture
def test_db():
    # Create test database
    engine = create_engine('sqlite:///:memory:')
    Base.metadata.create_all(engine)
    Session = sessionmaker(bind=engine)
    session = Session()
    yield session
    session.close()

def test_user_order_relationship(test_db):
    # Create user
    user = User(name="Test User", email="test@example.com")
    test_db.add(user)
    test_db.commit()

    # Create order for user
    order = Order(user_id=user.id, total=99.99)
    test_db.add(order)
    test_db.commit()

    # Query user with orders
    db_user = test_db.query(User).filter(User.id == user.id).first()
    assert len(db_user.orders) == 1
    assert db_user.orders[0].total == 99.99
